def transform(grid):
    rows, cols = len(grid), len(grid[0])
    points = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = []
    for r in range(r0, r1 + 1):
        line = []
        for c in range(c0, c1 + 1):
            rr = rows + 1 - r
            if 0 <= rr < rows and grid[rr][c] != 8:
                val = grid[rr][c]
            elif c >= 3 and c < cols - 3:
                val = grid[r][2 * (cols // 2) - 1 - c]
            else:
                # The grid's mirrored source extends two cells beyond its left edge.
                val = grid[r][cols - (c0 + c1 + 1) + c]
            line.append(val)
        out.append(line)
    return out
